svg.script:
(function () {
  var DUR = 8000;

var baseVals = [182.8, 145.1, 135.6, 129.4];
var amps = [6.4, 5.2, 4.8, 4.4];
var els = [0,1,2,3].map(function (i) { return document.getElementById('dl-v-' + i); });
function renderAt(p) {
  for (var i = 0; i < 4; i++) {
    if (!els[i]) continue;
    var s = Math.sin(2 * Math.PI * (p + i * 0.12)) - Math.sin(2 * Math.PI * (i * 0.12));
    els[i].textContent = (baseVals[i] + amps[i] * s * 0.5).toFixed(1) + 'M';
  }
}

  var manual = false;
  window.__seekSvgTime = function (tMs) {
    manual = true;
    renderAt((((tMs / DUR) % 1) + 1) % 1);
  };
  renderAt(0);
  if (typeof requestAnimationFrame === 'function') {
    var t0 = performance.now();
    function loop(now) {
      if (manual) return;
      renderAt(((now - t0) % DUR) / DUR);
      requestAnimationFrame(loop);
    }
    requestAnimationFrame(loop);
  }
})();
